using Microsoft.AspNetCore.Authorization; using Microsoft.AspNetCore.Mvc; using Microsoft.EntityFrameworkCore; using OrcaFacil.Application.Abstractions; using OrcaFacil.Persistence;
namespace OrcaFacil.Web.Pages.Settings;
[Authorize] public sealed class SetupModel(OrcaFacilDbContext db,ICurrentAccountService current):Microsoft.AspNetCore.Mvc.RazorPages.PageModel
{public sealed record Item(string Title,bool Done,string Page,string Action,string Responsible,DateTime? CompletedAt);public IReadOnlyList<Item> Items{get;private set;}=[];public int Progress=>Items.Count==0?0:(int)Math.Round(Items.Count(x=>x.Done)*100d/Items.Count);
 public async Task<IActionResult> OnGetAsync(CancellationToken ct){if(current.AccountId is not Guid id)return Forbid();var account=await db.BusinessAccounts.AsNoTracking().SingleAsync(x=>x.Id==id&&!x.IsDeleted,ct);var settings=await db.AccountSettings.AsNoTracking().SingleOrDefaultAsync(x=>x.AccountId==id&&!x.IsDeleted,ct);var clients=await db.Clients.AsNoTracking().Where(x=>x.AccountId==id&&!x.IsDeleted).OrderBy(x=>x.CreatedAt).Select(x=>(DateTime?)x.CreatedAt).FirstOrDefaultAsync(ct);var services=await db.ServiceCatalogItems.AsNoTracking().Where(x=>x.AccountId==id&&!x.IsDeleted).OrderBy(x=>x.CreatedAt).Select(x=>(DateTime?)x.CreatedAt).FirstOrDefaultAsync(ct);var members=await db.AccountMembers.AsNoTracking().CountAsync(x=>x.AccountId==id&&!x.IsDeleted,ct);var who=User.Identity?.Name??"Administrador da conta";Items=[new("Dados da empresa preenchidos",!string.IsNullOrWhiteSpace(account.DisplayName)&&!string.IsNullOrWhiteSpace(account.Email),"/Settings/Company","Revisar empresa",who,account.UpdatedAt??account.CreatedAt),new("Logo configurada",!string.IsNullOrWhiteSpace(settings?.LogoPath),"/Settings/Branding","Configurar marca",who,settings?.UpdatedAt),new("CNPJ/CPF configurado",!string.IsNullOrWhiteSpace(account.DocumentNumber),"/Settings/Company","Informar documento",who,account.UpdatedAt),new("Contato comercial configurado",!string.IsNullOrWhiteSpace(account.Phone),"/Settings/Company","Adicionar contato",who,account.UpdatedAt),new("Catálogo de serviços criado",services.HasValue,"/Services/Index","Cadastrar serviço",who,services),new("Primeiro cliente cadastrado",clients.HasValue,"/Clients/Index","Cadastrar cliente",who,clients),new("Modelo de proposta configurado",!string.IsNullOrWhiteSpace(settings?.DefaultNotes),"/Settings/Documents","Configurar proposta",who,settings?.UpdatedAt),new("Condições comerciais configuradas",!string.IsNullOrWhiteSpace(settings?.DefaultCommercialTerms),"/Settings/Commercial","Definir condições",who,settings?.UpdatedAt),new("Dados de pagamento configurados",!string.IsNullOrWhiteSpace(settings?.PixKey)||!string.IsNullOrWhiteSpace(settings?.BankAccount),"/Settings/Payments","Configurar recebimento",who,settings?.UpdatedAt),new("Usuários convidados",members>1,"/Settings/Users","Gerenciar equipe",who,null),new("Plano conferido",!string.IsNullOrWhiteSpace(account.CurrentPlanCode),"/Subscription/Index","Conferir plano",who,account.UpdatedAt),new("URL pública preparada",!string.IsNullOrWhiteSpace(settings?.Website),"/Settings/Company","Informar site",who,settings?.UpdatedAt)];return Page();}}
